use puddly_db::{RecordingExecutor, SqlValue};
use puddly_migrate::{apply_migrations, sql_body_for_apply};
use std::path::{Path, PathBuf};

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap()
}

#[test]
fn sql_body_strips_metadata_comments() {
    let raw = "\
-- puddly migration 0001_init
-- puddly-schema-fingerprint: abc
-- Generated by Puddly; review before applying.
-- puddly-schema-json: {}\n\
\n\
CREATE TABLE \"x\" (\"id\" UUID);\n";
    let body = sql_body_for_apply(raw);
    assert!(!body.contains("fingerprint"));
    assert!(!body.contains("schema-json"));
    assert!(body.contains("CREATE TABLE"));
}

#[test]
fn apply_migrations_records_ledger_and_sql() {
    let root = workspace_root().join("examples/todo-slice");
    let mut exec = RecordingExecutor::new();
    // First query: applied_names → empty
    exec.push_canned(vec![]);
    let result = apply_migrations(&root, &mut exec).unwrap();
    assert!(!result.applied.is_empty());
    assert!(result.applied.iter().any(|n| n.contains("0001_init")));

    // Ledger create + migration statements + insert into puddly_migrations
    assert!(exec
        .log
        .iter()
        .any(|q| q.sql.contains("puddly_migrations")));
    assert!(exec.log.iter().any(|q| q.sql.contains("CREATE TABLE")));
    assert!(exec.log.iter().any(|q| {
        q.sql.contains("INSERT INTO \"puddly_migrations\"")
            && q.params == vec![SqlValue::Text("0001_init.sql".into())]
    }));
}
